window.docContents[205].resolve({"/Development-Server/#serve":{"contents":"Verso includes a small HTTP server for previewing generated HTML on your own machine.\nRun it with lake exe verso-serve.\n\nThe server is for local development only.\nIt offers no HTTPS and no authentication.\nDo not use it to serve a real site.\n\n\n\n\n\n\n\n\n\n\n\n","context":"Writing Documentation in Lean with Verso","header":"9. Development Server","id":"/Development-Server/#serve"}});